    41  public class AnthropicToolsHelper {
    42  
    43      private static final Logger log = LoggerFactory.getLogger(AnthropicToolsHelper.class);
    44  
    45      /**
    46       * Apply tools to the message create params builder.
    47       *
    48       * @param builder The message create params builder
    49       * @param tools List of tool schemas
    50       * @param options Generate options containing tool choice
    51       */
    52      public static void applyTools(
    53              MessageCreateParams.Builder builder, List<ToolSchema> tools, GenerateOptions options) {
    54          if (tools == null || tools.isEmpty()) {
    55              return;
    56          }
    57  
    58          // Convert and add tools
    59          for (ToolSchema schema : tools) {
    60              Tool tool =
    61                      Tool.builder()
    62                              .name(schema.getName())
    63                              .description(schema.getDescription())
    64                              .inputSchema(convertToJsonValue(schema.getParameters()))
    65                              .build();
    66  
    67              builder.addTool(tool);
    68          }
    69  
    70          // Apply tool choice if specified
    71          if (options != null && options.getToolChoice() != null) {
    72              applyToolChoice(builder, options.getToolChoice());
    73          }
    74      }
    75  
    76      /**
    77       * Convert tool parameters map to Anthropic JsonValue.
    78       */
    79      private static JsonValue convertToJsonValue(Object parameters) {
    80          try {
    81              return JsonValue.from(ObjectMappers.jsonMapper().valueToTree(parameters));
    82          } catch (Exception e) {
    83              log.error("Failed to convert tool parameters to JsonValue", e);
    84              return JsonValue.from(null);
    85          }
    86      }
