    89       * Apply tool choice to the builder.
    90       */
    91      private static void applyToolChoice(
    92              MessageCreateParams.Builder builder, ToolChoice toolChoice) {
    93          if (toolChoice instanceof ToolChoice.Auto) {
    94              builder.toolChoice(ofAuto(ToolChoiceAuto.builder().build()));
    95          } else if (toolChoice instanceof ToolChoice.None) {
    96              // Anthropic doesn't have None, use Any instead
    97              builder.toolChoice(ofAny(ToolChoiceAny.builder().build()));
    98          } else if (toolChoice instanceof ToolChoice.Required) {
    99              // Anthropic doesn't have a direct "required" option, use "any" which forces tool
   100              // use
   101              log.warn(
   102                      "Anthropic API doesn't support ToolChoice.Required directly, using 'any'"
   103                              + " instead");
   104              builder.toolChoice(ofAny(ToolChoiceAny.builder().build()));
   105          } else if (toolChoice instanceof ToolChoice.Specific specific) {
   106              builder.toolChoice(ofTool(ToolChoiceTool.builder().name(specific.toolName()).build()));
   107          } else {
   108              log.warn("Unknown tool choice type: {}", toolChoice);
   109          }
   110      }
